-- Batch G (plan SCG-r1, "Speed as the centre grows"; audit REL-2, REL-3, REL-6).
-- Forward-only and transactional; it changes no row, table, column, trigger,
-- schedule or existing grant. Who can see or change which rows does not change.
--
-- 1. Policies (D1 = A, D2 = A): every public policy evaluates the zero-argument
--    role helpers once per statement (an InitPlan), and the 13 bare per-row
--    teacher-helper policies test the role first. The block is generated by
--    scripts/generate-rls-role-evaluation.mjs from the 123 catalog; the restore is
--    scripts/rollback/124_speed_as_the_centre_grows_restore.sql.
-- 2. search_students_page, re-created from its latest definition (121) with the
--    same signature, ACL and output: the payment status is computed only for the
--    learners it can affect (the page, or the candidates when a payment filter is set).
-- 3. Activity log: an index and two read functions (keyset page, table names).
-- 4. Reports: four aggregate read functions; report days are Casablanca civil
--    dates from public.business_date() (zone name, never a fixed offset).
-- Every new function is SECURITY INVOKER: row visibility is the caller's RLS.
begin;

-- Build order: refuse, changing nothing.
do $$ begin
  if to_regprocedure('portal_security.teacher_sees(uuid,uuid)') is null
    or to_regprocedure('public.business_date(timestamptz)') is null then
    raise exception 'Batch G requires migrations 122 and 123 first' using errcode = '55000';
  end if;
  if exists (select 1 from pg_policies where schemaname = 'public'
      and coalesce(qual, '') || coalesce(with_check, '') ~ '\(\s*SELECT\s+(get_my_role|get_my_teacher_id|get_my_email|auth\.uid)\(\)') then
    raise exception 'Batch G: a public policy is already wrapped' using errcode = '55000';
  end if;
end $$;

