-- ── 2. Students list (REL-2) ─────────────────────────────────────────────
-- 121 + Batch G: the learner filters run first; finance covers only the scope.
CREATE OR REPLACE FUNCTION public.search_students_page(p_search text DEFAULT ''::text, p_status text DEFAULT ''::text, p_age_category text DEFAULT ''::text, p_session text DEFAULT ''::text, p_level text DEFAULT ''::text, p_incomplete boolean DEFAULT false, p_source text DEFAULT ''::text, p_plan text DEFAULT ''::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20, p_group text DEFAULT ''::text, p_payment text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare v_result jsonb;
begin
  if p_page < 1 or p_page_size < 0 or p_page_size > 100
    or pg_catalog.length(p_search) > 120
    or coalesce(p_payment, '') not in ('', 'due', 'unpaid', 'partial', 'overdue', 'paid', 'none') then
    raise exception 'Invalid student page request' using errcode = '22023';
  end if;
  if p_page_size = 0 and public.get_my_role()='receptionist' then
    raise exception 'Student export forbidden' using errcode='42501';
  end if;
  if p_page_size = 0 and p_page <> 1 then
    raise exception 'Export page must be first page' using errcode = '22023';
  end if;

  -- Batch G: the learner filters run first; the finance aggregate covers only the
  -- learners it can affect (the page when no payment filter is set, else the candidates).
  with candidates as materialized (
    select s.*
    from public.students s
    where (
      p_status = 'all_shown'
      or (coalesce(p_status,'') = '' and s.status in ('Enrolled','Trial'))
      or (p_status not in ('','all_shown') and s.status = p_status)
    )
    and (coalesce(p_group,'') = '' or
      (p_group = 'unassigned' and (
        exists (select 1 from public.enrollments e where e.student_id = s.id
          and e.status = 'Confirmed' and e.group_id is null)
        or (s.status in ('Enrolled','Trial') and not exists (select 1 from public.enrollments e
          where e.student_id = s.id and e.group_id is not null and e.status in ('Validated','Trial'))
          and not exists (select 1 from public.enrollments e where e.student_id = s.id
            and e.status in ('Submitted','Under Review','Confirmed'))))))
    and (coalesce(p_age_category,'') = '' or s.age_category = p_age_category)
    and (coalesce(p_session,'') = '' or s.session_type = p_session)
    and (coalesce(p_level,'') = '' or s.niveau_cefr = p_level)
    and (not coalesce(p_incomplete,false) or (s.email is null or s.email = '') and (s.parent_email is null or s.parent_email = ''))
    and (coalesce(p_source,'') = '' or s.referral_source = p_source)
    and (coalesce(p_plan,'') = '' or coalesce(s.plan_type,'Standard') = p_plan)
    and (coalesce(p_search,'') = '' or pg_catalog.strpos(pg_catalog.lower(coalesce(s.full_name,'')),pg_catalog.lower(p_search)) > 0
      or pg_catalog.strpos(pg_catalog.lower(coalesce(s.email,'')),pg_catalog.lower(p_search)) > 0)
  ), scope as materialized (
    select c.id from candidates c where coalesce(p_payment, '') <> ''
    union all
    select p.id from (select c.id from candidates c where coalesce(p_payment, '') = ''
      order by c.created_at desc, c.id asc
      limit nullif(p_page_size,0)
      offset case when p_page_size = 0 then 0 else (p_page - 1) * p_page_size end) p
  ), finance as materialized (
    select sc.id as student_id, f.charge_count, f.payment_balance, f.has_overdue, f.has_partial
    from scope sc
    cross join lateral (
      select count(*) as charge_count,
        sum(c.balance)::numeric(12,2) as payment_balance,
        bool_or(c.balance > 0 and c.settlement_status = 'En retard') as has_overdue,
        bool_or(c.balance > 0 and c.paid_amount > 0) as has_partial
      from public.charge_balances c
      where c.voided_at is null and c.student_id = sc.id
      having count(*) > 0) f
  ), priced as materialized (
    select s.*,
      coalesce(f.payment_balance, 0)::numeric(12,2) as payment_balance,
      case
        when f.charge_count is null then 'Aucun engagement'
        when f.payment_balance <= 0 then 'Soldé'
        when f.has_overdue then 'En retard'
        when f.has_partial then 'Acompte versé'
        else 'En attente'
      end as payment_status
    from candidates s
    left join finance f on f.student_id = s.id
  ), filtered as materialized (
    select * from priced
    where coalesce(p_payment, '') = ''
      or (p_payment = 'due' and payment_balance > 0)
      or (p_payment = 'unpaid' and payment_status = 'En attente')
      or (p_payment = 'partial' and payment_status = 'Acompte versé')
      or (p_payment = 'overdue' and payment_status = 'En retard')
      or (p_payment = 'paid' and payment_status = 'Soldé')
      or (p_payment = 'none' and payment_status = 'Aucun engagement')
  ), rows as (
    select s.*,
      (select g.name from public.groups g where g.id = s.groupe_id) as group_name,
      (select count(*) from public.enrollments e where e.student_id = s.id and e.group_id is not null
        and e.status in ('Validated','Trial') and e.group_id is distinct from s.groupe_id) as extra_group_count,
      coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at, e.id)
        from public.enrollments e where e.student_id = s.id
          and e.status = 'Confirmed' and e.group_id is null), '[]'::jsonb) as pending_enrollments
    from (select * from filtered order by created_at desc, id asc
      limit nullif(p_page_size,0)
      offset case when p_page_size = 0 then 0 else (p_page - 1) * p_page_size end) s
  )
  select pg_catalog.jsonb_build_object(
    'rows',coalesce((select pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r) order by r.created_at desc,r.id asc) from rows r),'[]'::jsonb),
    'count',(select count(*) from filtered),
    'total',(select count(*) from public.students),
    'active_count',(select count(*) from public.students where status in ('Enrolled','Trial'))
  ) into v_result;
  return v_result;
end;
$function$;

-- ── 3. Activity log (REL-3) ──────────────────────────────────────────────
create index activity_log_created_id_idx on public.activity_log (created_at desc, id desc);

-- One page, newest first, without the before/after snapshots (loaded on expand).
-- p_from / p_to are Casablanca civil dates, both included.
create function public.list_activity_log(p_before_created_at timestamptz default null, p_before_id uuid default null,
  p_table text default '', p_action text default '', p_from date default null, p_to date default null,
  p_search text default '', p_limit integer default 50)
returns table(id uuid, created_at timestamptz, actor_email text, action text, target_table text, target_id uuid,
  changed_columns text[])
language plpgsql stable set search_path = pg_catalog, pg_temp as $$
begin
  if p_limit is null or p_limit < 1 or p_limit > 100 or pg_catalog.length(coalesce(p_search, '')) > 120
    or (p_before_created_at is null) <> (p_before_id is null)
    or coalesce(p_action, '') not in ('', 'INSERT', 'UPDATE', 'DELETE')
    or (p_from is not null and p_to is not null and p_to < p_from) then
    raise exception 'Invalid activity log request' using errcode = '22023';
  end if;
  return query
  select a.id, a.created_at, a.actor_email, a.action, a.target_table, a.target_id, a.changed_columns
  from public.activity_log a
  where (a.created_at, a.id) < (coalesce(p_before_created_at, 'infinity'::timestamptz),
      coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid))
    and (coalesce(p_table, '') = '' or a.target_table = p_table)
    and (coalesce(p_action, '') = '' or a.action = p_action)
    and (p_from is null or a.created_at >= (p_from::timestamp at time zone 'Africa/Casablanca'))
    and (p_to is null or a.created_at < ((p_to + 1)::timestamp at time zone 'Africa/Casablanca'))
    and (coalesce(p_search, '') = ''
      or pg_catalog.strpos(pg_catalog.lower(coalesce(a.actor_email, '')), pg_catalog.lower(p_search)) > 0
      or pg_catalog.strpos(pg_catalog.lower(a.target_table), pg_catalog.lower(p_search)) > 0
      or pg_catalog.strpos(coalesce(a.target_id::text, ''), pg_catalog.lower(p_search)) > 0)
  order by a.created_at desc, a.id desc
  limit p_limit;
end;
$$;

-- The logged table names, through a loose scan of idx_activity_log_target.
create function public.list_activity_log_tables()
returns setof text language sql stable set search_path = pg_catalog, pg_temp as $$
  with recursive t(name) as (
    (select a.target_table from public.activity_log a order by a.target_table limit 1)
    union all
    select (select a.target_table from public.activity_log a where a.target_table > t.name order by a.target_table limit 1)
    from t where t.name is not null)
  select t.name from t where t.name is not null order by t.name
$$;

-- ── 4. Reports (REL-3, REL-6) ────────────────────────────────────────────
-- Attendance per Casablanca civil day and status over the last p_days days,
-- today included; every day and status is present (zero when empty). A status
-- left empty counts as Présent, as the page did. The rows in the window are
-- counted first, then laid on the day/status grid; JIT costs more than it saves
-- on a query this small.
create function public.report_attendance_daily(p_days integer)
returns table(day date, status text, n bigint)
language plpgsql stable set search_path = pg_catalog, pg_temp set jit = off as $$
declare v_today date := public.business_date();
begin
  if p_days is null or p_days not in (7, 30, 90) then
    raise exception 'Invalid report request' using errcode = '22023';
  end if;
  return query
  with counts as (
    select a.session_date as day, coalesce(a.status, 'Présent') as status, count(*) as n
    from public.attendance a
    where a.session_date between v_today - (p_days - 1) and v_today
    group by 1, 2)
  select d.day, s.status, coalesce(c.n, 0)::bigint
  from (select (v_today - g)::date as day from pg_catalog.generate_series(0, p_days - 1) g) d
  cross join (values ('Présent'), ('Absent'), ('Retard'), ('Justifié')) s(status)
  left join counts c on c.day = d.day and c.status = s.status
  order by d.day, s.status;
end;
$$;

-- Payroll of one year per teacher (the record, else the name), named after the
-- latest row, largest net first; ties keep the latest-first order of the page.
create function public.report_payroll_by_teacher(p_year integer)
returns table(teacher_key text, teacher_name text, brut numeric, net numeric, n bigint)
language sql stable set search_path = pg_catalog, pg_temp as $$
  select k.teacher_key, k.teacher_name, k.brut, k.net, k.n from (
    select coalesce(p.teacher_id::text, nullif(p.teacher_name, ''), 'unknown') as teacher_key,
      coalesce(nullif((pg_catalog.array_agg(p.teacher_name order by p.created_at desc, p.id))[1], ''), '—') as teacher_name,
      sum(coalesce(p.salaire_brut, 0)) as brut, sum(coalesce(p.salaire_net, 0)) as net, count(*) as n,
      min(p.rn) as first_seen
    from (select x.*, row_number() over (order by x.created_at desc, x.id) as rn from public.payroll x
      where x.annee = p_year::text) p
    group by 1) k
  order by k.net desc, k.first_seen
$$;

-- Learners per status (empty counts as Prospect), in the order of first
-- appearance by name, as the page listed them.
create function public.report_student_mix()
returns table(status text, n bigint)
language sql stable set search_path = pg_catalog, pg_temp as $$
  select m.status, m.n from (
    select coalesce(s.status, 'Prospect') as status, count(*) as n, min(s.rn) as first_seen
    from (select x.status, row_number() over (order by x.full_name, x.id) as rn from public.students x) s
    group by 1) m
  order by m.first_seen
$$;

-- Report years: the Casablanca current year and the two before, plus every year
-- with a receipt or a payroll line; newest first.
create function public.report_years()
returns table(year integer, is_current boolean)
language sql stable set search_path = pg_catalog, pg_temp as $$
  with current_year as (select extract(year from public.business_date())::integer as y)
  select y.year, y.year = (select c.y from current_year c) from (
    select (select c.y from current_year c) - g as year from pg_catalog.generate_series(0, 2) g
    union
    select distinct extract(year from r.date)::integer from public.receipts r where r.date is not null
    union
    select distinct p.annee::integer from public.payroll p where p.annee ~ '^[0-9]{4}$') y
  order by y.year desc
$$;

-- New read functions: authenticated only; RLS decides every row.
do $$ declare f text; begin
  foreach f in array array[
    'public.list_activity_log(timestamptz,uuid,text,text,date,date,text,integer)', 'public.list_activity_log_tables()',
    'public.report_attendance_daily(integer)', 'public.report_payroll_by_teacher(integer)',
    'public.report_student_mix()', 'public.report_years()'] loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end $$;

notify pgrst, 'reload schema';
commit;
